onReceive(remote){ t=Math.max(now, remote.wall); if(t===hlc.wall && t===remote.wall){ hlc.logic=Math.max(hlc.logic, remote.logic)+1; } else if(t===hlc.wall){ hlc.logic=hlc.logic; } else if(t===remote.wall){ hlc.logic=remote.logic; } hlc.wall=t; }

